class ExpiringCache:
    def __init__(self):
        self.data = {}

    def set(self, key, value, ttl, now):
        self.data[key] = (value, now + ttl)

    def get(self, key, now):
        item = self.data.get(key)
        if not item:
            return None
        value, expires_at = item
        if now >= expires_at:
            del self.data[key]
            return None
        return value

