export class ExpiringCache<V> {
  private data = new Map<string, { value: V; expiresAt: number }>();
  set(key: string, value: V, ttl: number, now: number): void {
    this.data.set(key, { value, expiresAt: now + ttl });
  }
  get(key: string, now: number): V | undefined {
    const item = this.data.get(key);
    if (!item) return undefined;
    if (now >= item.expiresAt) { this.data.delete(key); return undefined; }
    return item.value;
  }
}

