class ExpiringCache<V> {
  record Entry<V>(V value, long expiresAt) {}
  private final Map<String, Entry<V>> data = new HashMap<>();
  void set(String key, V value, long ttl, long now) { data.put(key, new Entry<>(value, now + ttl)); }
  V get(String key, long now) {
    Entry<V> item = data.get(key);
    if (item == null) return null;
    if (now >= item.expiresAt()) { data.remove(key); return null; }
    return item.value();
  }
}

