import heapq

class ExpiringCacheHeap:
    def __init__(self):
        self.data = {}
        self.heap = []

    def set(self, key, value, ttl, now):
        expires = now + ttl
        self.data[key] = (value, expires)
        heapq.heappush(self.heap, (expires, key))

    def cleanup(self, now):
        while self.heap and self.heap[0][0] <= now:
            expires, key = heapq.heappop(self.heap)
            if self.data.get(key, (None, None))[1] == expires:
                del self.data[key]

