export class ExpiringCacheHeap<V> {
  private data = new Map<string, { value: V; expiresAt: number }>();
  private heap: Array<[number, string]> = [];
  set(key: string, value: V, ttl: number, now: number): void {
    const expiresAt = now + ttl;
    this.data.set(key, { value, expiresAt });
    this.heap.push([expiresAt, key]);
    this.heap.sort((a, b) => a[0] - b[0]);
  }
  cleanup(now: number): void {
    while (this.heap.length && this.heap[0][0] <= now) {
      const [expiresAt, key] = this.heap.shift()!;
      if (this.data.get(key)?.expiresAt === expiresAt) this.data.delete(key);
    }
  }
}

