def has_cycle(graph):
    color = {}
    def dfs(node):
        if color.get(node) == 1:
            return True
        if color.get(node) == 2:
            return False
        color[node] = 1
        for nxt in graph.get(node, []):
            if dfs(nxt):
                return True
        color[node] = 2
        return False
    return any(dfs(node) for node in graph)

