export function hasCycle(graph: Map<string, string[]>): boolean {
  const color = new Map<string, number>();
  function dfs(node: string): boolean {
    if (color.get(node) === 1) return true;
    if (color.get(node) === 2) return false;
    color.set(node, 1);
    for (const next of graph.get(node) ?? []) if (dfs(next)) return true;
    color.set(node, 2);
    return false;
  }
  return [...graph.keys()].some(dfs);
}

