export function hasCycleKahn(graph: Map<string, string[]>): boolean {
  const indegree = new Map<string, number>();
  for (const node of graph.keys()) indegree.set(node, indegree.get(node) ?? 0);
  for (const nodes of graph.values()) for (const node of nodes) indegree.set(node, (indegree.get(node) ?? 0) + 1);
  const queue = [...indegree.entries()].filter(([, deg]) => deg === 0).map(([node]) => node);
  let seen = 0;
  for (let i = 0; i < queue.length; i += 1) {
    const node = queue[i];
    seen += 1;
    for (const next of graph.get(node) ?? []) {
      indegree.set(next, indegree.get(next)! - 1);
      if (indegree.get(next) === 0) queue.push(next);
    }
  }
  return seen !== indegree.size;
}

