boolean hasCycleKahn(Map<String, List<String>> graph) {
  Map<String, Integer> indegree = new HashMap<>();
  for (String node : graph.keySet()) indegree.putIfAbsent(node, 0);
  for (List<String> nodes : graph.values()) for (String node : nodes) indegree.merge(node, 1, Integer::sum);
  Queue<String> queue = new ArrayDeque<>();
  for (Map.Entry<String, Integer> e : indegree.entrySet()) if (e.getValue() == 0) queue.add(e.getKey());
  int seen = 0;
  while (!queue.isEmpty()) {
    String node = queue.remove(); seen++;
    for (String next : graph.getOrDefault(node, List.of())) if (indegree.merge(next, -1, Integer::sum) == 0) queue.add(next);
  }
  return seen != indegree.size();
}

