export function longestDistinct(items: string[]): number {
  const seen = new Set<string>();
  let left = 0;
  let best = 0;
  for (let right = 0; right < items.length; right += 1) {
    while (seen.has(items[right])) seen.delete(items[left++]);
    seen.add(items[right]);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

